css = '''
.marketingGrid{display:grid;grid-template-columns:1.05fr .95fr;gap:18px}.marketCard{padding:24px}.marketCard h3{margin:0;color:var(--n);font-size:24px}.marketCard p{margin:5px 0 0;color:var(--muted);font-size:12px}.marketRows{display:grid;gap:9px;margin-top:15px}.marketRow{display:grid;grid-template-columns:42px 1fr;gap:11px;padding:13px;border-radius:16px;background:#FAF7F2}.marketRow i{width:42px;height:42px;border-radius:13px;display:grid;place-items:center;background:#E9E2D7;color:var(--n);font:800 13px Arial!important;font-style:normal}.marketRow:nth-child(3) i,.marketRow:nth-child(4) i{background:#F2E4D4;color:#8A5A27}.marketRow b,.marketRow span{display:block}.marketRow b{color:var(--n);font-size:13px}.marketRow span{color:var(--muted);font-size:10px;margin-top:2px}.routeCard{padding:24px;background:linear-gradient(145deg,var(--n3),var(--n));color:#fff;border-radius:28px}.routeCard h3{margin:0;color:#fff;font-size:25px}.routeCard p{margin:5px 0 0;color:rgba(255,255,255,.72);font-size:12px}.routeFlow{display:grid;gap:8px;margin-top:16px}.routeNode{padding:12px 14px;border-radius:15px;background:rgba(255,255,255,.07);border:1px solid rgba(255,255,255,.11)}.routeNode b,.routeNode span{display:block}.routeNode b{color:#F0C38E;font-size:12px}.routeNode span{color:rgba(255,255,255,.75);font-size:10px;margin-top:2px}.routeArrow{text-align:center;color:#E2A45E;font:900 18px Arial!important}.exemptBox{margin-top:18px;padding:22px;border-radius:24px;background:#FFF8EF;border:1px solid #E6C8A5}.exemptBox h3{margin:0;color:var(--n);font-size:23px}.exemptBox p{margin:4px 0 0;color:var(--muted);font-size:12px}.exemptStats{display:grid;grid-template-columns:repeat(4,1fr);gap:9px;margin-top:14px}.exemptStat{background:#fff;border:1px solid #EADFD0;border-radius:15px;padding:12px}.exemptStat small,.exemptStat b,.exemptStat span{display:block}.exemptStat small{font-size:8px;color:#8A6640}.exemptStat b{font:800 18px Arial!important;color:var(--n);margin-top:2px}.exemptStat span{font-size:9px;color:var(--muted);margin-top:2px}.brokerGrid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin-top:17px}.brokerCase{padding:15px;border-radius:17px;border:1px solid var(--line);background:#fff}.brokerCase b,.brokerCase span{display:block}.brokerCase b{color:var(--n);font-size:13px}.brokerCase span{color:var(--muted);font-size:10px;margin-top:3px}.brokerCase.hot{background:#FFF7EC;border-color:#E8C69E}.snam{margin-top:18px;padding:22px;border-radius:24px;background:#F7F3ED;border:1px solid #DDD3C7;position:relative;overflow:hidden}.snam:before{content:"";position:absolute;inset:0 auto 0 0;width:6px;background:var(--g)}.snam .tag{display:inline-flex;padding:4px 8px;border-radius:999px;background:#EFE4D7;color:#8A5A27;font-size:9px;font-weight:800}.snam h3{margin:8px 0 5px;color:var(--n);font-size:23px}.snam p{margin:0;color:var(--muted);font-size:12px}.snamGrid{display:grid;grid-template-columns:repeat(3,1fr);gap:9px;margin-top:13px}.snamGrid div{padding:12px;border-radius:14px;background:#fff;border:1px solid #E7DED3}.snamGrid b,.snamGrid span{display:block}.snamGrid b{color:var(--n);font-size:11px}.snamGrid span{color:var(--muted);font-size:9px;margin-top:2px}@media(max-width:930px){.marketingGrid{grid-template-columns:1fr}.exemptStats,.brokerGrid,.snamGrid{grid-template-columns:1fr 1fr}}@media(max-width:620px){.exemptStats,.brokerGrid,.snamGrid{grid-template-columns:1fr}}
'''
if '.marketingGrid{' not in s:
    marker = '.compare{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}'
    if marker not in s:
        raise SystemExit('missing CSS marker')
    s = s.replace(marker, css + marker, 1)

section = '''
<section class="sec white" id="marketing"><div class="c"><div class="head"><span class="ey">التسويق والدعوة للدخول</span><h2>التسويق يرفع الحساسية التنظيمية، والتكييف يبدأ من طبيعة ما يعرض</h2><p>المفتاح هنا هو الفصل بين عقد مضاربة تجاري ثنائي، وبرنامج استثمار مشترك، وورقة مالية مثل السهم أو الوحدة. طريقة الوصول إلى المستثمر عنصر مهم، بينما الطبيعة الاقتصادية والقانونية للمنتج تبقى محور التكييف.</p></div><div class="marketingGrid"><div class="card marketCard"><h3>ماذا يتغير بحسب طريقة وصول المستثمر؟</h3><p>هذه الحالات تقيس أثر الدعوة والترويج على مستوى الفحص، مع بقاء الحكم النهائي مرتبطا بالعقد وطريقة إدارة الأموال.</p><div class="marketRows"><div class="marketRow"><i>1</i><div><b>الشخص جاء من تلقاء نفسه</b><span>هذه الصورة تقوي وصف العلاقة كتفاوض ثنائي مباشر عندما يكون لكل طرف عقده ورأس ماله وحسابه وتسويته.</span></div></div><div class="marketRow"><i>2</i><div><b>تواصل مباشر مع دائرة محددة ومعروفة</b><span>تزداد أهمية توثيق سبب التواصل وصفة الأطراف وطبيعة العلاقة، خصوصا عند تكرار العقود وتشابه شروطها.</span></div></div><div class="marketRow"><i>3</i><div><b>حملة أو دعوة واسعة للدخول</b><span>تتحول طريقة جمع الأموال إلى عنصر تنظيمي قوي، وخصوصا عندما تتحد السياسة الاستثمارية والعوائد والإدارة.</span></div></div><div class="marketRow"><i>4</i><div><b>وسيط أو معرف يجلب أطرافا بصورة متكررة</b><span>تظهر أهمية فحص صفته ومقابله وتعليماته والمواد التي يستخدمها، لأن النشاط قد يتحول من معرفة عابرة إلى ترويج غير مباشر أو ترتيب إذا كان المعروض ورقة مالية.</span></div></div></div></div><div class="routeCard"><h3>أين تبدأ هيئة السوق المالية؟</h3><p>قائمة الأوراق المالية الحالية تشمل الأسهم وأدوات الدين والوحدات والمشتقات وغيرها. عقد المضاربة التجاري الثنائي يعالج في الأصل ضمن نظام المعاملات المدنية، بينما الانتقال إلى وحدات أو أسهم أو برنامج استثمار مشترك يفتح أطر هيئة السوق بحسب الحالة.</p><div class="routeFlow"><div class="routeNode"><b>عقد ثنائي مستقل</b><span>رب مال محدد + مضارب محدد + رأس مال وحساب وتسوية مستقلة</span></div><div class="routeArrow">↓</div><div class="routeNode"><b>تجميع وسياسة موحدة ومشاركة جماعية في الأرباح</b><span>يقترب الوصف من تعريف صندوق الاستثمار، ومدير الصندوق في التعليمات المبسطة يجب أن يكون مؤسسة سوق مالية مرخصة.</span></div><div class="routeArrow">↓</div><div class="routeNode"><b>أسهم أو وحدات أو أوراق مالية</b><span>تدخل قواعد الطرح أو قواعد الصناديق بحسب نوع المنتج. في الأسهم يعد الإصدار نفسه صورة من صور الطرح، إلى جانب الدعوة والترويج المباشر أو غير المباشر.</span></div></div></div></div><div class="brokerGrid"><div class="brokerCase"><b>قدوم المستثمر بلا دعوة</b><span>يقوي وصف العلاقة الثنائية. ومع وجود أموال مجمعة وسياسة واحدة ومشاركة جماعية في الأرباح يبقى فحص البرنامج الجماعي قائما.</span></div><div class="brokerCase"><b>وسيط مستقل بلا تكليف أو مقابل</b><span>تكون صلته بالشركة أضعف من ناحية الإسناد، ويحتاج الواقع إلى فحص الرسائل والعمولات والمواد المستخدمة وتكرار الإحالات.</span></div><div class="brokerCase hot"><b>وسيط بعمولة أو مواد أو تعليمات</b><span>ترتفع قرينة الترويج غير المباشر. وإذا كان المعروض ورقة مالية، فتعريف أعمال الترتيب يشمل تقديم أشخاص فيما يتعلق بطرح الأوراق المالية.</span></div></div><div class="exemptBox"><span class="ey">عند التحول إلى أسهم</span><h3>الطرح المستثنى مسار للأوراق المالية بشروط محددة</h3><p>القواعد المحدثة في 2026 تضع حالة للطرح المستثنى عندما تقل كامل قيمة الأوراق المالية المطروحة عن عشرة ملايين ريال، مع ضوابط إضافية. هذا المسار يخدم إصدار الأسهم والأوراق المالية الخاضعة للقواعد. وحدات صناديق الاستثمار لها إطار مستقل في لوائح وتعليمات الصناديق.</p><div class="exemptStats"><div class="exemptStat"><small>إجمالي قيمة الطرح</small><b>&lt; 10m</b><span>أقل من عشرة ملايين ريال</span></div><div class="exemptStat"><small>غير المؤهلين والمؤسسيين</small><b>≤ 50</b><span>عدد المطروح عليهم</span></div><div class="exemptStat"><small>لكل مطروح عليه منهم</small><b>≤ 200k</b><span>ريال لكل شخص</span></div><div class="exemptStat"><small>التكرار</small><b>1 / 12m</b><span>مرة واحدة خلال الاثني عشر شهرا التالية لاكتمال الطرح</span></div></div><div class="caption">الطرح المستثنى يبقى داخل الإطار التنظيمي، وتشمل القواعد إشعار الهيئة ربع سنويا بمعلومات الطروحات المستثناة.</div></div><div class="snam"><span class="tag">مثال تطبيقي منشور من هيئة السوق المالية</span><h3>واقعة سنام الأعمال: التسويق صار جزءا من أساس الدعوى</h3><p>في نوفمبر 2025 أعلنت هيئة السوق المالية قبول طلب تقييد دعوى جماعية من مستثمر ضد شركة سنام الأعمال للتجارة القابضة بعد حملة تسويقية عن طرح أسهم شركة سنام النمو لخدمات الأعمال القابضة التابعة لها، مع الادعاء بعدم اتباع إجراءات قواعد طرح الأوراق المالية واكتتاب المستثمر بناء على الحملة. وفي مارس 2026 اعتمدت لجنة الفصل الدعوى الجماعية بعد اكتمال العدد النظامي للطلبات.</p><div class="snamGrid"><div><b>طبيعة الواقعة</b><span>طرح أسهم لشركة تابعة</span></div><div><b>العنصر البارز</b><span>حملة تسويقية ثم اكتتاب</span></div><div><b>الدلالة لهذه الدراسة</b><span>أثر التسويق عندما يكون المعروض ورقة مالية، مع بقاء الواقعة خاصة بالأسهم وليست قياسا آليا على عقد المضاربة الثنائي</span></div></div><div class="caption">الاستشهاد يقتصر على الأثر التنظيمي للتسويق في واقعة أسهم منشورة رسميا. اعتماد الدعوى الجماعية إجراء قضائي جماعي بحسب الإعلانات المنشورة، ويختلف عن صدور حكم نهائي في أصل المسؤولية.</div></div></div></section>
'''
if 'id="marketing"' not in s:
    marker = '<section class="sec soft" id="compare">'
    if marker not in s:
        raise SystemExit('missing compare marker')
    s = s.replace(marker, section + marker, 1)

sources = '''<details class="src"><summary>هيئة السوق المالية · قائمة الأوراق المالية وأعمال الترتيب</summary><div class="srcBody"><p>قائمة المصطلحات تعد الأسهم وأدوات الدين والوحدات والمشتقات وغيرها أوراقا مالية. لائحة أعمال الأوراق المالية تعرف الترتيب بأنه تقديم أشخاص فيما يتعلق بطرح الأوراق المالية أو تقديم الاستشارات في أعمال تمويل الشركات.</p><div class="quote">التطبيق العملي: دور الوسيط يصبح أكثر حساسية عندما يكون المعروض ورقة مالية ويكون دوره متكررا أو منظما أو بمقابل.</div><a href="https://cma.org.sa/RulesRegulations/Regulations/Documents/Amended%20Securities%20Business%20Regulations-ar.pdf" target="_blank" rel="noopener">فتح لائحة أعمال الأوراق المالية</a></div></details><details class="src"><summary>قواعد طرح الأوراق المالية 2026 · تعريف الطرح والطرح المستثنى</summary><div class="srcBody"><p>المادة الأولى تعد إصدار الورقة المالية ودعوة الجمهور والترويج المباشر أو غير المباشر من صور الطرح. المادة السادسة تتضمن حالة طرح مستثنى تقل قيمته عن عشرة ملايين ريال مع شروط العدد والحد الفردي والتكرار وإقرار المخاطر.</p><div class="quote">في حالة أقل من عشرة ملايين: حتى 50 مطروحا عليه من غير العملاء المؤهلين والمؤسسيين، وبحد 200,000 ريال لكل واحد منهم، ومرة واحدة خلال الاثني عشر شهرا التالية لاكتمال الطرح.</div><div class="quote">الطارح أو مؤسسة السوق المالية عند توجيه الطرح تشعر الهيئة ربع سنويا بالطروحات المستثناة ومعلوماتها.</div><a href="https://www.uqn.gov.sa/decisions-and-regulations/4001355" target="_blank" rel="noopener">فتح القواعد المحدثة</a></div></details><details class="src"><summary>تعليمات صناديق الاستثمار المبسطة 2026 · المدير والتوزيع والإعلان</summary><div class="srcBody"><p>التعليمات تشترط أن يكون مدير الصندوق مؤسسة سوق مالية مرخصة، وتنظم الموزع والإعلان وطرح الوحدات. الإعلان عن الصندوق يوجه إلى فئات العملاء التي يجوز طرح الوحدات عليها وفق التعليمات.</p><div class="quote">مدير الصندوق المبسط يجب أن يكون مؤسسة سوق مالية مرخصا لها في إدارة الاستثمارات وتشغيل الصناديق أو إدارة الاستثمارات.</div><a href="https://www.uqn.gov.sa/decisions-and-regulations/4000963" target="_blank" rel="noopener">فتح التعليمات</a></div></details><details class="src"><summary>هيئة السوق المالية · واقعة سنام الأعمال 2025 و2026</summary><div class="srcBody"><p>أعلنت الهيئة أن أساس الطلب الجماعي تضمن حملة تسويقية عن طرح أسهم شركة تابعة مع الادعاء بعدم اتباع الإجراءات النظامية، ثم أعلنت في 2026 اعتماد الدعوى الجماعية بعد اكتمال الطلبات.</p><div class="quote">الواقعة تخص طرح أسهم، وتستخدم في هذه الدراسة كمثال على وزن التسويق عندما يكون المنتج ورقة مالية.</div><a href="https://cma.gov.sa/MediaCenter/NEWS/Pages/CMA_N_3907.aspx" target="_blank" rel="noopener">فتح إعلان قبول طلب تقييد الدعوى</a><br><a href="https://cma.gov.sa/MediaCenter/NEWS/Pages/CMA_N_4020.aspx" target="_blank" rel="noopener">فتح الإعلان الإلحاقي لعام 2026</a></div></details>'''
if 'واقعة سنام الأعمال 2025 و2026' not in s:
    marker = '<details class="src"><summary>البنك المركزي السعودي · نظام مراقبة البنوك</summary>'
    if marker not in s:
        raise SystemExit('missing sources marker')
    s = s.replace(marker, sources + marker, 1)

p.write_text(s, encoding='utf-8')
print('patched study')
